@Test
void 거울에_넣기() {
    Team team = new Team("A팀");
    Member m = new Member("김");
    em.persist(team);
    em.persist(m);

    team.getMembers().add(m);       // 거울에만 넣는다
    em.flush();
    em.clear();

    Member found = memberRepository.findById(m.getId()).orElseThrow();
    System.out.println("team_id: " + found.getTeam());
}

